3	import { useEffect, useMemo, useRef, useState } from "react";
4	import Link from "next/link";
5	import {
6	  ArrowLeft, ArrowRight, Car, Check, CircleAlert, CircleMinus, CirclePlus, Factory, HandCoins, Info, Landmark, Mountain,
7	  Recycle, RotateCcw, ShieldAlert, Sprout, TrainFront, Trees, User, Users, Waves, Wheat,
