13	import { AGRI, PACHT, STAND } from "@/lib/invest/markt";
14	import { fmt } from "@/lib/rechner/annahmen";
15	
16	const SCHRITTE = ["Standort", "Fläche", "Besonderheiten", "Netz & Eigentum"];
17	const NUTZUNG_ICON = { acker: Wheat, gruenland: Sprout, konversion: Factory, deponie: Recycle, parkplatz: Car, sonstige: Info };
18	const BES_ICON = { randstreifen: TrainFront, benachteiligt: Wheat, schutzgebiet: ShieldAlert, wald: Trees, hang: Mountain, ueberschwemmung: Waves };
19	const EIG_ICON = { allein: User, gemeinschaft: Users, verpachtet: HandCoins, kommune: Landmark };
20	const AMPEL = {
21	  gruen: { label: "Gut geeignet", text: "Ihre Fläche bringt gute Voraussetzungen mit. Jetzt lohnt die genaue Prüfung.", farbe: "#669933", ton: "bg-ov-500" },
22	  gelb: { label: "Bedingt geeignet", text: "Möglich – aber einzelne Punkte müssen wir genau prüfen, bevor es konkret wird.", farbe: "#ffc53d", ton: "bg-sun-400" },
23	  rot: { label: "Eher schwierig", text: "Als klassischer Solarpark schwierig. Oft gibt es trotzdem Wege – etwa Agri-PV, Nachbarflächen oder ein Carport.", farbe: "#c4cad5", ton: "bg-ink-300" },
24	};
25	const spanne = (a, b) => (b >= 1e6 ? `${fmt(a / 1e6, 2)}–${fmt(b / 1e6, 2)} Mio. €` : `${fmt(a / 1000)}–${fmt(b / 1000)} Tsd. €`);
