218	                {BESONDERHEITEN.filter((b) => b.id !== "benachteiligt" || land === "DE").map((b) => {
219	                  const an = besonderheiten.includes(b.id);
220	                  const Icon = BES_ICON[b.id];
221	                  return (
222	                    <label key={b.id} className={karte(an)}>
223	                      <input type="checkbox" checked={an} onChange={() => umschalten(b.id)} className="sr-only" />
224	                      <span className={iconBox(an)}>
225	                        <Icon aria-hidden="true" className="h-5 w-5" />
226	                      </span>
227	                      <span className="min-w-0 pr-6">
228	                        <span className="block font-display text-[16px] font-bold leading-snug text-ink-900">{b.label}</span>
229	                        <span className="block text-[13px] leading-snug text-ink-500">{b.text}</span>
230	                      </span>
231	                      <span aria-hidden="true" className={cn("absolute right-4 top-4 flex h-6 w-6 items-center justify-center rounded-full transition-all", an ? "bg-ov-500 text-white" : "bg-white ring-1 ring-ink-300")}>
232	                        {an && <Check className="h-3.5 w-3.5" strokeWidth={3} />}
233	                      </span>
234	                    </label>
235	                  );
236	                })}
237	              </div>
238	            </fieldset>
239	          )}
240	
241	          {/* 4 Netz & Eigentum */}
242	          {schritt === 3 && (
243	            <div className="space-y-9">
244	              <fieldset>
245	                <legend className={legende}>Wie weit ist es bis zum Stromnetz?</legend>
246	                <p className="mt-2 text-[15.5px] text-ink-600">Gemeint ist die nächste Mittelspannungsleitung (Freileitung auf Betonmasten, Trafostation) oder ein Umspannwerk.</p>
247	                <div className="mt-6 grid grid-cols-2 gap-2 sm:grid-cols-3 lg:grid-cols-6">
248	                  {NETZ.map((n) => {
249	                    const an = netz === n.id;
250	                    return (
251	                      <label key={n.id} className={cn("flex min-h-[56px] cursor-pointer items-center justify-center rounded-2xl px-3 py-2 text-center text-[14.5px] font-semibold transition-all focus-within:ring-2 focus-within:ring-ov-500", an ? "bg-ov-50 text-ov-800 ring-2 ring-ov-500" : "bg-sand-50 text-ink-800 ring-1 ring-ink-200 hover:bg-white")}>
252	                        <input type="radio" name="netz" value={n.id} checked={an} onChange={() => setNetz(n.id)} className="sr-only" />
253	                        {n.label}
254	                      </label>
255	                    );
256	                  })}
257	                </div>
258	              </fieldset>
259	              <fieldset>
260	                <legend className="text-[15px] font-semibold text-ink-800">Wem gehört die Fläche?</legend>
261	                <div className="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-4">
262	                  {EIGENTUM.map((e) => {
263	                    const an = eigentum === e.id;
264	                    const Icon = EIG_ICON[e.id];
265	                    return (
266	                      <label key={e.id} className={karte(an)}>
267	                        <input type="radio" name="eigentum" value={e.id} checked={an} onChange={() => setEigentum(e.id)} className="sr-only" />
268	                        <span className={iconBox(an)}>
269	                          <Icon aria-hidden="true" className="h-5 w-5" />
270	                        </span>
271	                        <span className="min-w-0">
272	                          <span className="block font-display text-[15.5px] font-bold leading-snug text-ink-900">{e.label}</span>
273	                          <span className="block text-[13px] leading-snug text-ink-500">{e.text}</span>
274	                        </span>
275	                      </label>
276	                    );
277	                  })}
278	                </div>
279	              </fieldset>
280	            </div>
281	          )}
282	
283	          {schritt === 4 && ergebnis && (
284	            <Ergebnis e={ergebnis} eingaben={{ land, regionId, ha, nutzung, besonderheiten, netz, eigentum }} onNeu={neu} onAendern={gehe} />
285	          )}
286	        </div>
287	
288	        {schritt < 4 && (
289	          <div className="mt-10 flex flex-col-reverse items-stretch justify-between gap-3 border-t border-ink-100 pt-6 sm:flex-row sm:items-center">
290	            {schritt > 0 ? (
291	              <button type="button" onClick={() => gehe(schritt - 1)} className="inline-flex h-12 items-center justify-center gap-2 rounded-full px-5 text-[15px] font-semibold text-ink-700 hover:bg-ink-100">
292	                <ArrowLeft aria-hidden="true" className="h-4 w-4" /> Zurück
293	              </button>
294	            ) : (
295	              <p className="text-[13px] text-ink-500">Schritt 1 von 4 · dauert ca. 2 Minuten · ohne Anmeldung</p>
296	            )}
297	            <button
298	              type="button"
299	              disabled={!weiterOk}
300	              onClick={() => gehe(schritt + 1)}
