          {frei && <DatenblattAnzeige projekt={{ ...p, vertraulich: d.vertraulich || {}, datenblatt: d.datenblatt || {} }} untertitel="Angaben des Anbieters – Wirtschaftlichkeit ungeprüft" />}
          {bestandAkte && <AnbieterAkte akte={bestandAkte} />}

