// Aufruf: node shot.mjs <pfad> [breite] [voll=1] [name]
import { chromium } from "playwright";
import { fileURLToPath } from "node:url";
const [pfad = "/", breite = "1440", voll = "1", name] = process.argv.slice(2);
const b = await chromium.launch();
const p = await b.newPage({ viewport: { width: +breite, height: +breite < 600 ? 844 : 900 }, deviceScaleFactor: 1 });
const fehler = [];
p.on("pageerror", (e) => fehler.push("PAGEERROR " + e.message));
p.on("console", (m) => m.type() === "error" && fehler.push("CONSOLE " + m.text().slice(0, 300)));
const r = await p.goto("http://localhost:3100" + pfad, { waitUntil: "networkidle", timeout: 120000 });
await p.evaluate(async () => {
  document.querySelectorAll(".ov-reveal").forEach((e) => e.classList.add("is-visible"));
  document.querySelectorAll("img[loading=lazy]").forEach((i) => (i.loading = "eager"));
  for (let y = 0; y < document.body.scrollHeight; y += 700) { window.scrollTo(0, y); await new Promise((r) => setTimeout(r, 60)); }
  window.scrollTo(0, 0);
});
// Cookie-Banner für Screenshots schließen (nur notwendige)
try { await p.getByRole("button", { name: "Nur notwendige" }).click({ timeout: 1500 }); } catch {}
await p.waitForTimeout(1200);
const datei = `${name || (pfad.replace(/\W+/g, "_") || "root")}_${breite}.png`;
await p.screenshot({ path: fileURLToPath(new URL("./shots/" + datei, import.meta.url)), fullPage: voll === "1" });
console.log(r.status(), datei, fehler.length ? "\n" + fehler.join("\n") : "");
await b.close();

// node deal_portal.mjs <email|-> <breite> <name> <pfad1> [pfad2 ...] – ein Browser, immer geschlossen
import { chromium } from "playwright";
import { fileURLToPath } from "node:url";
const [email, breite = "1440", name = "p", ...pfade] = process.argv.slice(2);
const B = "http://localhost:3100";
const b = await chromium.launch();
try {
  const ctx = await b.newContext({ viewport: { width: +breite, height: +breite < 600 ? 844 : 900 } });
  if (email !== "-") {
    const r = await ctx.request.post(B + "/api/auth/login", { data: { email, passwort: "Demo-2026!" }, headers: { Origin: B }, timeout: 180000 });
    console.log("login", r.status());
  }
  for (const pfad of pfade) {
    const p = await ctx.newPage();
    const fehler = [];
    p.on("pageerror", (e) => fehler.push("PAGEERROR " + e.message.slice(0, 300)));
    p.on("console", (m) => m.type() === "error" && fehler.push("CONSOLE " + m.text().slice(0, 300)));
    try {
      const res = await p.goto(B + pfad, { waitUntil: "load", timeout: 180000 });
      await p.waitForTimeout(2500);
      const breiteDoc = await p.evaluate(() => document.documentElement.scrollWidth);
      const datei = `deal_${name}_${pfad.replace(/\W+/g, "_")}_${breite}.png`;
      await p.screenshot({ path: fileURLToPath(new URL("./shots/" + datei, import.meta.url)), fullPage: true });
      console.log(res.status(), pfad, datei, breiteDoc > +breite ? `UEBERLAUF ${breiteDoc}` : "", fehler.length ? "\n" + fehler.join("\n") : "");
    } catch (e) {
      console.log("FEHLER", pfad, e.message.slice(0, 200));
    } finally {
      await p.close();
    }
  }
} finally {
  await b.close();
}
