// UX-Audit: node ux_lauf.mjs <email|-> <breite> <name> <pfad1> [pfad2 ...]
// Ein Browser, immer geschlossen. Pfad "@muster" = ersten Link der vorigen Seite öffnen, dessen href das Muster enthält.
// Je Seite: Ladezeit, Überlauf, Höhe, H1, kleine Ziele (<24px), Felder ohne Label, Bild ohne alt, Viewport-Screenshot.
import { chromium } from "playwright";
import { fileURLToPath } from "node:url";
const [email, breite = "1440", name = "p", ...pfade] = process.argv.slice(2);
const B = "http://localhost:3100";
const b = await chromium.launch();
try {
  const ctx = await b.newContext({ viewport: { width: +breite, height: +breite < 600 ? 844 : 900 } });
  await ctx.addCookies([{ name: "ov_cookie", value: "notwendig", url: B }]).catch(() => {});
  if (email !== "-") {
    const r = await ctx.request.post(B + "/api/auth/login", { data: { email, passwort: "Demo-2026!" }, headers: { Origin: B }, timeout: 180000 });
    console.log("login", email, r.status());
  }
  const p = await ctx.newPage();
  const fehler = [];
  p.on("pageerror", (e) => fehler.push("PAGEERROR " + e.message.slice(0, 200)));
  let links = [];
  let i = 0;
  for (let pfad of pfade) {
    i++;
    fehler.length = 0;
    if (pfad.startsWith("@")) {
      const m = pfad.slice(1);
      const ziel = links.find((h) => h.includes(m));
      if (!ziel) { console.log("KEIN LINK fuer", m); continue; }
      pfad = ziel.replace(B, "");
    }
    try {
      const t0 = Date.now();
      const res = await p.goto(B + pfad, { waitUntil: "load", timeout: 180000 });
      const ms = Date.now() - t0;
      try { await p.getByRole("button", { name: "Nur notwendige" }).click({ timeout: 1200 }); } catch {}
      await p.waitForTimeout(1500);
      const m = await p.evaluate(() => {
        const vis = (e) => { const r = e.getBoundingClientRect(); const s = getComputedStyle(e); return r.width > 0 && r.height > 0 && s.visibility !== "hidden" && s.display !== "none"; };
        const ziele = [...document.querySelectorAll("a[href],button,input:not([type=hidden]),select,textarea,[role=button],[role=tab]")].filter(vis);
        const klein = ziele.filter((e) => { const r = e.getBoundingClientRect(); return (r.width < 24 || r.height < 24) && !e.closest("p,li") ; });
        const felder = [...document.querySelectorAll("input:not([type=hidden]):not([type=checkbox]):not([type=radio]),select,textarea")].filter(vis);
        const ohneLabel = felder.filter((f) => !(f.labels && f.labels.length) && !f.getAttribute("aria-label") && !f.getAttribute("aria-labelledby"));
        const h1 = [...document.querySelectorAll("h1")].map((h) => h.textContent.trim().slice(0, 60));
        return {
          scrollW: document.documentElement.scrollWidth,
          hoehe: document.documentElement.scrollHeight,
          h1,
          ziele: ziele.length,
          klein: klein.length,
          kleinBsp: klein.slice(0, 4).map((e) => (e.getAttribute("aria-label") || e.textContent || e.tagName).trim().slice(0, 30)),
          felder: felder.length,
          ohneLabel: ohneLabel.length,
          ohneLabelBsp: ohneLabel.slice(0, 3).map((f) => f.name || f.placeholder || f.type),
          bilderOhneAlt: [...document.images].filter((x) => !x.hasAttribute("alt")).length,
          titel: document.title,
          links: [...document.querySelectorAll("a[href]")].map((a) => a.href),
        };
      });
      links = m.links;
      const datei = `ux_${name}_${String(i).padStart(2, "0")}_${pfad.replace(/\W+/g, "_").slice(0, 50)}_${breite}.png`;
      await p.screenshot({ path: fileURLToPath(new URL("./shots/" + datei, import.meta.url)), fullPage: false });
      console.log(JSON.stringify({ s: res.status(), pfad, ms, datei, ueberlauf: m.scrollW > +breite ? m.scrollW : 0, hoehe: m.hoehe, h1: m.h1, titel: m.titel, ziele: m.ziele, klein: m.klein, kleinBsp: m.kleinBsp, felder: m.felder, ohneLabel: m.ohneLabel, ohneLabelBsp: m.ohneLabelBsp, altFehlt: m.bilderOhneAlt, fehler: [...fehler] }));
    } catch (e) {
      console.log("FEHLER", pfad, e.message.slice(0, 200));
    }
  }
} finally {
  await b.close();
}

