// UX-Audit Flächencheck interaktiv: node ux_fc.mjs <breite> – zählt Klicks, prüft Zahlenfeld, Fokus, Ergebnis
import { chromium } from "playwright";
import { fileURLToPath } from "node:url";
const breite = +(process.argv[2] || 390);
const B = "http://localhost:3100";
const shot = (p, n, voll = false) => p.screenshot({ path: fileURLToPath(new URL(`./shots/ux_fc_${n}_${breite}.png`, import.meta.url)), fullPage: voll });
const b = await chromium.launch();
try {
  const ctx = await b.newContext({ viewport: { width: breite, height: breite < 600 ? 844 : 900 } });
  await ctx.addCookies([{ name: "cookieConsent", value: encodeURIComponent(JSON.stringify({ essential: true })), url: B }]);
  const p = await ctx.newPage();
  await p.goto(B + "/flaechencheck", { waitUntil: "load", timeout: 180000 });
  await p.waitForTimeout(2500);
  const wizTop = await p.evaluate(() => document.querySelector('section[aria-label="Flächencheck"]').getBoundingClientRect().top);
  console.log("Wizard-Oberkante im ersten Viewport (px):", Math.round(wizTop));
  let klicks = 0;
  const k = async (loc) => { await loc.click({ timeout: 20000 }); klicks++; await p.waitForTimeout(350); };
  await k(p.locator("label", { hasText: "Deutschland" }).first());
  await shot(p, "1_land");
  const regionen = p.locator('input[name="region"]');
  if (await regionen.count()) await k(p.locator("label:has(input[name=region])").first());
  const weiterAus = await p.getByRole("button", { name: /Weiter/ }).isDisabled();
  await k(p.getByRole("button", { name: /Weiter/ }));
  // Zahlenfeld: leeren und 25 tippen
  const zahl = p.locator('input[type="number"]').first();
  await zahl.click(); await zahl.press("Control+a"); await zahl.press("Backspace");
  const nachLeeren = await zahl.inputValue();
  await zahl.type("25");
  const nachTippen = await zahl.inputValue();
  console.log("Zahlenfeld nach Leeren:", nachLeeren, "nach Tippen 25:", nachTippen);
  const weiterOhneNutzung = await p.getByRole("button", { name: /Weiter/ }).isDisabled();
  await k(p.locator("label:has(input[name=nutzung])").first());
  await shot(p, "2_flaeche");
  await k(p.getByRole("button", { name: /Weiter/ }));
  await shot(p, "3_besonderheiten");
  await k(p.getByRole("button", { name: /weiter/i }));
  await k(p.locator("label:has(input[name=netz])").first());
  await k(p.locator("label:has(input[name=eigentum])").first());
  await shot(p, "4_netz");
  const fokusVor = await p.evaluate(() => document.activeElement?.tagName + "." + (document.activeElement?.className || "").slice(0, 30));
  await k(p.getByRole("button", { name: /Ergebnis anzeigen/ }));
  await p.waitForTimeout(1200);
  const fokusNach = await p.evaluate(() => (document.activeElement?.textContent || document.activeElement?.tagName).slice(0, 60));
  await shot(p, "5_ergebnis");
  console.log({ klicks, weiterAnfangsGesperrt: weiterAus, weiterOhneNutzungGesperrt: weiterOhneNutzung, fokusVor, fokusNach });
  // Formular: leeres Absenden → native Validierung?
  const form = p.locator("form").filter({ has: p.getByRole("button", { name: /Ergebnis senden/ }) });
  await form.scrollIntoViewIfNeeded();
  await shot(p, "6_formular");
