// node ux_ueberlauf.mjs <email> <breite> <pfad> – listet Elemente, die rechts über den Viewport hinausragen
import { chromium } from "playwright";
const [email, breite = "390", pfad] = process.argv.slice(2);
const B = "http://localhost:3100";
const b = await chromium.launch();
try {
  const ctx = await b.newContext({ viewport: { width: +breite, height: 844 } });
  await ctx.addCookies([{ name: "cookieConsent", value: encodeURIComponent(JSON.stringify({ essential: true })), url: B }]);
  if (email !== "-") await ctx.request.post(B + "/api/auth/login", { data: { email, passwort: "Demo-2026!" }, headers: { Origin: B }, timeout: 180000 });
  const p = await ctx.newPage();
  await p.goto(B + pfad, { waitUntil: "load", timeout: 180000 });
  await p.waitForTimeout(2500);
  const r = await p.evaluate((w) => {
    const out = [];
    for (const e of document.querySelectorAll("body *")) {
      const r = e.getBoundingClientRect();
      if (r.right > w + 1 && r.width > 0) {
        let x = e, versteckt = false;
        while ((x = x.parentElement)) { const s = getComputedStyle(x); if (["auto", "scroll", "hidden", "clip"].includes(s.overflowX)) { versteckt = true; break; } }
        if (!versteckt) out.push(`${e.tagName}.${String(e.className).slice(0, 60)} right=${Math.round(r.right)} "${(e.textContent || "").trim().slice(0, 40)}"`);
      }
    }
    return { sw: document.documentElement.scrollWidth, out: out.slice(0, 8) };
  }, +breite);
  console.log(JSON.stringify(r, null, 1));
} finally {
  await b.close();
}

