import { chromium } from "playwright";
import { fileURLToPath } from "node:url";
const breite = +(process.argv[2] || 390);
const B = "http://localhost:3100";
const shot = (p, n) => p.screenshot({ path: fileURLToPath(new URL(`./shots/ux_sp_${n}_${breite}.png`, import.meta.url)) });
const b = await chromium.launch();
try {
  const ctx = await b.newContext({ viewport: { width: breite, height: breite < 600 ? 844 : 900 } });
  await ctx.addCookies([{ name: "cookieConsent", value: encodeURIComponent(JSON.stringify({ essential: true })), url: B }]);
  const p = await ctx.newPage();
  await p.goto(B + "/rechner/solarpark", { waitUntil: "load", timeout: 180000 });
  await p.waitForTimeout(2500);
  await shot(p, "1_start");
  const slider = p.locator('input[type="range"]').first();
  const yRechner = await slider.evaluate((e) => e.getBoundingClientRect().top + window.scrollY);
  console.log("erster Regler bei y =", Math.round(yRechner));
  await slider.scrollIntoViewIfNeeded();
  await p.evaluate(() => window.scrollBy(0, -200));
  await p.waitForTimeout(500);
  const vorher = await p.evaluate(() => document.querySelector("dl")?.innerText.replace(/\n/g, " | ").slice(0, 160));
  await slider.focus();
  for (let i = 0; i < 5; i++) await slider.press("ArrowRight");
  await p.waitForTimeout(800);
  const nachher = await p.evaluate(() => document.querySelector("dl")?.innerText.replace(/\n/g, " | ").slice(0, 160));
  await shot(p, "2_eingaben");
  const anzahlRegler = await p.locator('input[type="range"]').count();
  const ergebnisY = await p.evaluate(() => { const h = [...document.querySelectorAll("h2")].find((x) => /Ergebnis/.test(x.textContent)); return h ? Math.round(h.getBoundingClientRect().top + window.scrollY) : null; });
  console.log({ anzahlRegler, ergebnisY, mobilKurzVorher: vorher, mobilKurzNachher: nachher });
} finally {
  await b.close();
}

